/* Configuration list and live-test UI. The transport is deliberately simulated. */
window.LiekanAIConfig = function ({root,esc,icon,button,shell,toast,getScene,onAvailabilityChange}) {
  const presets=window.LiekanModelPresets, storageKey='liekan-ai-prototype-apis', protocolName=p=>p==='anthropic'?'Anthropic Messages':'OpenAI Chat Completions';
  let rows=[],lastScene='',selected='deepseek',testRun=0,modal=null,triggerId=null,filter='',search='';
  const preset=id=>presets.find(p=>p.id===id)||presets.find(p=>p.id==='custom');
  const viewer=()=>getScene()==='viewer', routeMode=()=>new URLSearchParams(location.search).get('mode')||'list';
  const link=(mode='list',id='')=>{const u=new URL(location.href);u.searchParams.delete('view');u.searchParams.set('mode',mode);id?u.searchParams.set('id',id):u.searchParams.delete('id');return u.pathname+u.search;};
  const disabled=()=>viewer()?'disabled':'';
  const statusLabel={connected:'连接正常',failed:'连接失败',untested:'尚未测试',disabled:'已停用'};
  function fixtures() {return [['openai','日常数据分析','connected','867 ms',true],['claude','深度洞察分析','connected','1,248 ms',false],['deepseek','中文分析助手','failed','鉴权失败',false],['gemini','快速摘要','untested','',false]].map(([provider,name,status,latency,isDefault],i)=>({...preset(provider),id:'demo-api-'+i,presetId:provider,name,status,latency,isDefault,enabled:true,keyConfigured:true,space:'个人空间',tested:status==='untested'?'从未测试':'10-04 14:32'}));}
  function restore() {try {const saved=JSON.parse(sessionStorage.getItem(storageKey));if(Array.isArray(saved)&&saved.every(r=>typeof r.id==='string'&&typeof r.model==='string'&&typeof r.base==='string'&&['openai','anthropic'].includes(r.protocol))&&(getScene()!=='unconfigured'||saved.every(r=>!r.enabled)))return saved;}catch{}return getScene()==='unconfigured'?[]:fixtures();}
  function persist() {const metadata=rows.map(({id,presetId,name,model,base,protocol,space,status,latency,tested,isDefault,enabled,keyConfigured})=>({id,presetId,name,model,base,protocol,space,status,latency,tested,isDefault,enabled,keyConfigured}));sessionStorage.setItem(storageKey,JSON.stringify(metadata));const available=rows.filter(r=>r.enabled).length;lastScene=available?'ready':'unconfigured';onAvailabilityChange(available);}
  function rowMarkup(row) {const p=preset(row.presetId),state=row.enabled?row.status:'disabled';return `<tr data-api-id="${esc(row.id)}"><td><div class="api-name"><span class="provider-mark" data-provider="${p.id}">${p.mark}</span><div><strong>${esc(row.name)}</strong><small>${esc(row.space)} · ${p.provider}</small>${row.isDefault?'<span class="badge">默认分析模型</span>':''}</div></div></td><td><span class="api-model">${esc(row.model)}</span><small>${protocolName(row.protocol)}</small></td><td><code class="api-endpoint">${esc(row.base)}</code><small>${icon('key')} Key 已配置 · 隐藏</small></td><td><span class="api-status ${state}"><span class="dot"></span>${statusLabel[state]}</span><small>${esc(row.latency||'等待测试')}</small><small>最近测试：${esc(row.tested)}</small></td><td><div class="api-row-actions">${button('实时测试','api-test',false,`data-id="${esc(row.id)}" ${viewer()||!row.enabled?'disabled':''}`)}<a class="button" href="${link('edit',row.id)}" ${viewer()?'aria-disabled="true" tabindex="-1"':''}>编辑</a>${button(row.isDefault?'已默认':'设为默认','api-default',false,`data-id="${esc(row.id)}" ${viewer()||row.isDefault||!row.enabled?'disabled':''}`)}${button(row.enabled?'停用':'启用','api-toggle',false,`data-id="${esc(row.id)}" ${disabled()}`)}<button class="icon-button" data-action="api-delete" data-id="${esc(row.id)}" aria-label="删除 ${esc(row.name)}" ${disabled()}>${icon('close')}</button></div></td></tr>`;}
  function listPage() {
    const shown=rows.filter(r=>(!filter||r.status===filter)&&(!search||`${r.name} ${r.model} ${preset(r.presetId).provider}`.toLowerCase().includes(search.toLowerCase())));
    shell(`<div class="api-workspace"><div class="page-heading"><div><h1>AI配置器</h1><p>管理你的模型连接，随时检查连通情况，为快速发起选择默认模型。</p></div><div class="actions"><a class="button" href="${link('guide')}">${icon('file')}模型接入指南</a><a class="button primary" href="${link('new')}" ${viewer()?'aria-disabled="true" tabindex="-1"':''}>${icon('plus')}新建 API</a></div></div>${viewer()?'<div class="notice">当前成员可查看连接，API 配置与测试由空间管理员管理。</div>':''}<div class="api-overview"><span><strong>${rows.length}</strong>个 API</span><span><strong>${rows.filter(r=>r.enabled&&r.status==='connected').length}</strong>个连接正常</span><span><strong>${rows.filter(r=>r.enabled&&r.status==='failed').length}</strong>个需检查</span><span class="badge gray">列表与测试结果均为演示</span></div><section class="panel"><div class="panel-head api-list-head"><h2>已配置的 API</h2><div class="actions"><label class="sr-only" for="api-search">搜索 API</label><input id="api-search" class="list-search" type="search" placeholder="搜索名称或模型" value="${esc(search)}"><label class="sr-only" for="api-filter">连接状态</label><select id="api-filter" class="list-select"><option value="">全部状态</option>${['connected','failed','untested'].map(s=>`<option value="${s}" ${filter===s?'selected':''}>${statusLabel[s]}</option>`).join('')}</select></div></div>${rows.length?`<div class="table-wrap"><table class="api-list"><thead><tr><th scope="col">连接名称</th><th scope="col">模型与协议</th><th scope="col">API 信息</th><th scope="col">连通情况</th><th scope="col">操作</th></tr></thead><tbody>${shown.map(rowMarkup).join('')}</tbody></table></div>${shown.length?'':'<div class="api-empty"><h2>没有匹配的连接</h2><p>调整搜索词或连接状态后重试。</p></div>'}<div class="api-list-footer"><span>显示 ${shown.length} / ${rows.length} 个连接 · 测试不会读取网站日志</span><span>默认连接用于快速发起中的分析</span></div>`:`<div class="api-empty"><h2>还没有配置 AI API</h2><p>选择一个模型，补充 API Key，即可创建你的第一条连接。</p><a class="button primary" href="${link('new')}">${icon('plus')}新建 API</a></div>`}</section><section class="api-bottom"><div><h2>每个连接都可以独立测试</h2><p>实时测试展示请求准备、鉴权、模型调用和流式返回。异常时可根据结果检查 Key、地址与模型权限。</p></div><div><h2>选择模型，自动填好配置</h2><p>内置 OpenAI、Claude、Gemini、DeepSeek、千问、Kimi、MiniMax 模板。需要使用自建网关时，可选自定义兼容模型。</p></div></section><p class="footnote">交互原型 · 密钥不会保存或发送 · 官方模板核对日期：2026-10-04</p></div>`);
  }
  function input(label,name,value,help='',type='text') {return `<label class="field"><span class="field-title">${label}</span><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" autocomplete="off" maxlength="300" aria-describedby="${name}-error"><span class="field-help">${help}</span><span class="field-error" id="${name}-error" aria-live="polite"></span></label>`;}
  function formPage() {
    const editId=new URLSearchParams(location.search).get('id'),existing=routeMode()==='edit'?rows.find(r=>r.id===editId):null;
    if(viewer()){listPage();return;}if(routeMode()==='edit'&&!existing){toast('这条连接已不存在');navigate('list');return;}
    const p=preset(selected),draft=existing&&selected===existing.presetId?existing:{...p,name:p.id==='custom'?'':p.name+' · 数据分析',space:existing?.space||'个人空间'};
    shell(`<div class="api-workspace"><div class="page-heading"><div><h1>${existing?'编辑 API':'新建 API'}</h1><p>选择模型后，接口、协议和模型名称会自动填写，只需补充 API Key。</p></div><a class="button" href="${link()}">${icon('back')}返回 API 列表</a></div><form id="api-form" novalidate data-edit-id="${esc(existing?.id||'')}"><section class="preset-section"><h2>① 选择模型</h2><p>每次创建一个连接，可在列表中统一管理多个模型。</p><div class="provider-grid">${presets.map(item=>`<label class="provider-card"><input type="radio" name="preset" value="${item.id}" aria-label="${item.name}" ${item.id===selected?'checked':''}><span class="provider-mark" data-provider="${item.id}">${item.mark}</span><span><strong>${item.name}</strong><small>${item.provider} · ${item.region}</small></span></label>`).join('')}</div></section><div class="api-form-layout"><section class="panel"><div class="panel-head"><h2>② 补充 API Key</h2><span class="badge">${p.id==='custom'?'手动配置':'已自动填写'}</span></div><div class="panel-body"><dl class="autofill-info"><dt>连接名称</dt><dd id="preview-name">${esc(draft.name||'自定义连接')}</dd><dt>模型标识</dt><dd id="preview-model">${esc(draft.model||'请填写模型名称')}</dd><dt>API 地址</dt><dd id="preview-base">${esc(draft.base||'请填写接口地址')}</dd><dt>调用协议</dt><dd id="preview-protocol">${protocolName(draft.protocol)}</dd></dl><label class="field"><span class="field-title">API Key${existing&&selected===existing.presetId?'<span class="small muted">留空保留现有配置</span>':'<span class="required">*</span>'}</span><span class="password"><input id="api-key" name="api-key" type="password" autocomplete="off" spellcheck="false" maxlength="500" placeholder="原型请使用演示 Key" aria-describedby="api-key-error api-key-help"><button class="icon-button" type="button" data-action="api-show-key" aria-label="显示演示密钥" aria-pressed="false">${icon('eye')}</button></span><span class="field-help" id="api-key-help">${existing&&selected!==existing.presetId?'已更换模型供应商，请填写对应平台的 Key。 ':''}${p.note} 原型不保存或发送密钥。</span><span id="api-key-error" class="field-error" aria-live="polite"></span></label><div class="actions">${button('填入演示 Key','api-fill')}<a class="button text" href="${p.docs||link('guide')}" ${p.docs?'target="_blank" rel="noopener noreferrer"':''}>${icon('file')}${p.docs?'官方配置说明':'查看接入指南'}</a></div><details class="api-advanced" ${p.id==='custom'?'open':''}><summary>高级配置 · 名称、接口、模型与生效空间</summary>${input('连接名称','connection',draft.name)}${input('API 基础地址','endpoint',draft.base,'填写基础地址，系统自动拼接调用路径。','url')}${input('模型标识','model',draft.model)}<label class="field"><span class="field-title">调用协议</span><select id="protocol" name="protocol"><option value="openai" ${draft.protocol==='openai'?'selected':''}>OpenAI Chat Completions</option><option value="anthropic" ${draft.protocol==='anthropic'?'selected':''}>Anthropic Messages</option></select></label><label class="field"><span class="field-title">生效空间</span><select name="space" aria-label="生效空间"><option ${draft.space==='个人空间'?'selected':''}>个人空间</option><option ${draft.space==='移山增长团队'?'selected':''}>移山增长团队</option></select></label></details></div><div class="form-footer"><a class="button" href="${link()}">取消</a><span class="small muted">保存后可在列表实时测试</span><button class="button primary" type="submit">${icon('check')}保存 API</button></div></section><aside class="api-form-note"><h2>三步完成配置</h2><ol class="steps"><li>选择要使用的模型。</li><li>填写对应平台的 API Key。</li><li>保存后点击“实时测试”。</li></ol><div class="notice"><strong>模板适配说明</strong><br>${p.note}</div><div class="notice">测试使用简短的验证提问，无需读取网站数据。用于数据分析的默认连接，可在列表里切换。</div><a class="button text" href="${link('guide')}">${icon('file')}查看完整模型接入指南</a></aside></div></form></div>`);
  }
  function guidePage() {shell(`<div class="api-workspace"><div class="page-heading"><div><h1>模型接入指南</h1><p>核对日期：2026-10-04 · 模板采用官方直连接口，模型权限以你的账号为准。</p></div><a class="button" href="${link()}">${icon('back')}返回 API 列表</a></div><div class="notice">选择模型可自动填写通用参数。Key 需要来自对应平台和地域；自建网关可在高级配置中修改地址与模型。</div>${presets.filter(p=>p.id!=='custom').map(p=>`<section class="guide-provider"><h2>${p.name} <span class="badge gray">${p.region}</span></h2><dl class="autofill-info"><dt>模型标识</dt><dd>${p.model}</dd><dt>API 地址</dt><dd>${p.base}</dd><dt>协议</dt><dd>${protocolName(p.protocol)}</dd></dl><p>${p.note}</p><a href="${p.docs}" target="_blank" rel="noopener noreferrer">查看官方文档 ${icon('right')}</a>${p.modelDocs?` · <a href="${p.modelDocs}" target="_blank" rel="noopener noreferrer">官方模型列表</a>`:''}</section>`).join('')}<section class="guide-provider"><h2>连接问题如何排查</h2><p>401：检查 Key 与地域。403：检查模型权限。404：检查 API 地址和模型标识。429：检查额度或调用频率。超时：确认服务状态与网络。错误类型需结合实际响应判断。</p></section><p class="footnote">当前原型的测试过程与结果均为模拟；正式接入须由服务端执行请求并安全保存密钥。</p></div>`);}
  function navigate(mode,id='') {closeModal();history.pushState(null,'',link(mode,id));const row=rows.find(r=>r.id===id);selected=row?.presetId||'deepseek';render();document.querySelector('#main-content').focus();window.scrollTo(0,0);}
  function render() {if(lastScene!==getScene()){closeModal();rows=restore();lastScene=getScene();selected=rows.find(r=>r.id===new URLSearchParams(location.search).get('id'))?.presetId||'deepseek';search='';filter='';}const mode=routeMode();mode==='new'||mode==='edit'?formPage():mode==='guide'?guidePage():listPage();}
  function closeModal() {testRun++;if(modal){modal.close();modal.remove();modal=null;}if(triggerId)root.querySelector(`[data-action="api-test"][data-id="${CSS.escape(triggerId)}"]`)?.focus();triggerId=null;}
  function createModal(html,confirm=false) {closeModal();modal=document.createElement('dialog');modal.className='api-modal'+(confirm?' api-confirm':'');modal.setAttribute('aria-labelledby','modal-title');modal.innerHTML=html;document.body.append(modal);modal.addEventListener('cancel',event=>{event.preventDefault();closeModal();});modal.addEventListener('click',event=>{if(event.target===modal){const rect=modal.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeModal();}});modal.showModal();return modal;}
  const testPrompt='请用两句话说明你已准备好分析网站日志，并提醒我核对数据范围。';
  function openTest(row) {
    const p=preset(row.presetId);createModal(`<div class="modal-header"><div><h2 id="modal-title">实时测试</h2><p>${esc(row.name)} · ${esc(row.model)}</p></div><button class="icon-button" data-modal-action="close" aria-label="关闭实时测试">${icon('close')}</button></div><div class="test-banner"><span class="badge">原型模拟 · 无外部请求</span><label>测试场景 <select class="list-select" id="test-scenario" aria-label="测试场景"><option value="success">正常返回</option><option value="auth" ${row.status==='failed'?'selected':''}>Key 无效</option><option value="timeout">响应超时</option></select></label><span id="test-status" role="status" aria-live="polite">准备开始</span></div><div class="test-grid"><aside class="test-sidebar"><h3>连接检查</h3><ol class="test-stages">${['检查连接配置','验证访问凭证','调用指定模型','接收流式回答'].map((t,i)=>`<li class="test-stage" data-stage="${i}"><span class="stage-dot">${i+1}</span><div><strong>${t}</strong><small>等待执行</small></div></li>`).join('')}</ol><div class="test-facts"><div><small>首字耗时</small><strong id="first-token">等待</strong></div><div><small>总耗时</small><strong id="total-time">等待</strong></div><div><small>响应状态</small><strong id="http-status">等待</strong></div></div></aside><div class="test-output"><h3>请求摘要</h3><div class="request-preview"><dl class="autofill-info"><dt>方法</dt><dd>POST · ${protocolName(row.protocol)}</dd><dt>地址</dt><dd>${esc(row.base.replace(/\/$/,'')+(row.protocol==='anthropic'?'/messages':'/chat/completions'))}</dd><dt>模型</dt><dd>${esc(row.model)}</dd><dt>认证</dt><dd>${row.protocol==='anthropic'?'x-api-key: [已隐藏] · anthropic-version: 2023-06-01':'Authorization: Bearer [已隐藏]'}</dd></dl></div><h3>实时返回</h3><div class="test-prompt">测试提问：${testPrompt}</div><div class="test-answer" id="test-answer">等待模型返回…</div><div class="test-log" id="test-log" aria-label="测试事件记录"></div></div></div><div class="modal-footer"><span>测试提问仅验证连接与文本返回，所有结果均为演示。</span><button class="button" data-modal-action="close">关闭</button><button class="button primary" id="test-restart" data-modal-action="run">${icon('link')}重新测试</button></div>`);triggerId=row.id;
    modal.addEventListener('click',event=>{const action=event.target.closest('[data-modal-action]')?.dataset.modalAction;if(action==='close')closeModal();if(action==='run')runTest(row);});modal.querySelector('#test-scenario').addEventListener('change',()=>runTest(row));runTest(row);
  }
  async function runTest(row) {
    const dialog=modal,run=++testRun,started=performance.now(),scenario=dialog.querySelector('#test-scenario').value;
    const alive=()=>run===testRun&&modal===dialog&&dialog.open,wait=async ms=>{await new Promise(resolve=>setTimeout(resolve,ms));return alive();},find=s=>dialog.querySelector(s);
    find('#test-restart').disabled=true;find('#test-answer').textContent='等待模型返回…';find('#test-log').innerHTML='';find('#first-token').textContent='等待';find('#http-status').textContent='等待';find('#total-time').textContent='等待';
    const stage=(i,state,note)=>{const el=find(`[data-stage="${i}"]`);el.className='test-stage '+state;el.querySelector('small').textContent=note;el.querySelector('.stage-dot').innerHTML=state==='done'?icon('check'):state==='failed'?icon('close'):i+1;};
    const log=message=>{const el=document.createElement('div');el.textContent=`+${Math.round(performance.now()-started)} ms  ${message}`;find('#test-log').append(el);};
    for(let i=0;i<4;i++)stage(i,'','等待执行');find('#test-status').textContent='测试进行中';stage(0,'active','检查 API 地址与模型标识');log('开始模拟测试，密钥已隐藏');
    if(!await wait(350))return;stage(0,'done','参数格式通过');stage(1,'active','模拟验证 API Key');log('连接配置检查通过');
    if(!await wait(450))return;
    if(scenario==='auth'){stage(1,'failed','模拟响应：401 · invalid_api_key');finish(false,'401','Key 验证失败。请检查是否来自对应平台和地域，再更新凭证。');return;}
    stage(1,'done','模拟凭证验证通过');stage(2,'active','请求已发送，等待模型响应');log('凭证检查通过，开始模拟模型调用');
    if(!await wait(scenario==='timeout'?1400:450))return;
    if(scenario==='timeout'){stage(2,'failed','模拟响应超时');finish(false,'超时','模型响应超时。请检查服务状态与网络后重新测试。');return;}
    stage(2,'done','模拟响应：200 OK');stage(3,'active','正在接收文本片段');find('#http-status').textContent='200';find('#first-token').textContent=Math.round(performance.now()-started)+' ms';find('#test-answer').textContent='';log('收到模拟首个文本片段');
    const text=`连接已就绪，我可以结合网站抓取日志、AI 引荐、页面与转化记录，协助分析趋势并定位相关数据页。\n开始分析前，请确认选择的网站、时间范围与数据覆盖情况。`;
    for(let i=0;i<text.length;i+=5){if(!await wait(65))return;find('#test-answer').textContent+=text.slice(i,i+5);find('#total-time').textContent=Math.round(performance.now()-started)+' ms';}
    stage(3,'done','模拟流式回答接收完成');finish(true,'200','');
    function finish(success,http,error) {if(!alive())return;const elapsed=Math.round(performance.now()-started);find('#http-status').textContent=http;find('#total-time').textContent=elapsed+' ms';find('#test-status').textContent=success?'模拟测试通过':'模拟测试失败';if(error)find('#test-answer').textContent=error;log(success?'模拟测试完成，已更新列表状态':'模拟测试结束，请按提示检查配置');find('#test-restart').disabled=false;row.status=success?'connected':'failed';row.latency=success?elapsed+' ms':http==='401'?'鉴权失败':'请求超时';row.tested=new Date().toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false});persist();listPage();}
  }
  function save(event) {
    event.preventDefault();if(viewer())return;const form=event.target,existing=rows.find(r=>r.id===form.dataset.editId);let first=null;
    for(const name of ['connection','endpoint','model','api-key']){const el=form.elements[name];let error=el.value.trim()||name==='api-key'&&existing&&selected===existing.presetId?'':'请填写此项';if(name==='endpoint'&&!error){try{const u=new URL(el.value);if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash)error='请填写不含账号、查询参数和片段的 HTTPS 基础地址';}catch{error='请填写有效的 HTTPS 地址';}}document.getElementById(`${name}-error`).textContent=error;el.setAttribute('aria-invalid',String(Boolean(error)));if(error&&!first)first=el;}
    if(first){form.querySelector('.api-advanced').open=true;first.focus();return;}
    const p=preset(selected),data={id:existing?.id||crypto.randomUUID(),presetId:selected,name:form.elements.connection.value.trim(),model:form.elements.model.value.trim(),base:form.elements.endpoint.value.trim().replace(/\/$/,''),protocol:form.elements.protocol.value,space:form.elements.space.value,enabled:existing?.enabled??true,isDefault:false,keyConfigured:true,status:'untested',latency:'',tested:'从未测试'};
    form.elements['api-key'].value='';if(existing)rows=rows.map(r=>r.id===existing.id?data:r);else rows.push(data);persist();navigate('list');toast(existing?'API 配置已更新，请重新测试':'API 已创建，可从列表实时测试');
  }
  root.addEventListener('submit',event=>{if(event.target.id==='api-form')save(event);});
  root.addEventListener('change',event=>{if(event.target.name==='preset'){selected=event.target.value;formPage();root.querySelector(`input[name="preset"][value="${selected}"]`).focus();}if(event.target.id==='api-filter'){filter=event.target.value;listPage();}if(event.target.id==='protocol')refreshPreview();});
  function refreshPreview() {const f=root.querySelector('#api-form');if(!f)return;for(const [id,name] of [['preview-name','connection'],['preview-base','endpoint'],['preview-model','model']])root.querySelector('#'+id).textContent=f.elements[name].value;root.querySelector('#preview-protocol').textContent=protocolName(f.elements.protocol.value);}
  root.addEventListener('input',event=>{if(event.target.id==='api-search'){const pos=event.target.selectionStart;search=event.target.value;listPage();const input=root.querySelector('#api-search');input.focus();if(pos!==null)input.setSelectionRange(pos,pos);}if(event.target.closest('#api-form'))refreshPreview();});
  root.addEventListener('click',event=>{
    const anchor=event.target.closest('a[href]');if(anchor&&anchor.origin===location.origin&&anchor.pathname===location.pathname){const u=new URL(anchor.href);if(u.searchParams.has('mode')){event.preventDefault();if(viewer()&&['new','edit'].includes(u.searchParams.get('mode'))){toast('请联系空间管理员管理 API');return;}navigate(u.searchParams.get('mode'),u.searchParams.get('id')||'');return;}}
    const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const row=rows.find(r=>r.id===target.dataset.id);
    if(target.dataset.action==='api-fill'){root.querySelector('#api-key').value='demo-key-for-prototype-only';return;}
    if(target.dataset.action==='api-show-key'){const input=root.querySelector('#api-key'),show=input.type==='password';input.type=show?'text':'password';target.setAttribute('aria-label',show?'隐藏演示密钥':'显示演示密钥');target.setAttribute('aria-pressed',String(show));return;}
    if(!row||viewer())return;
    if(target.dataset.action==='api-test'&&row.enabled)openTest(row);
    if(target.dataset.action==='api-default'){if(row.status!=='connected'){toast('请先通过实时测试，再设为默认模型');return;}rows.forEach(r=>r.isDefault=r===row);persist();listPage();toast('默认分析模型已更新');}
    if(target.dataset.action==='api-toggle'){row.enabled=!row.enabled;if(!row.enabled)row.isDefault=false;persist();listPage();toast(row.enabled?'连接已启用':'连接已停用');}
    if(target.dataset.action==='api-delete'){const dialog=createModal(`<div class="modal-header"><h2 id="modal-title">删除 API 连接</h2></div><div class="confirm-body">确认删除“${esc(row.name)}”？<p class="muted small">删除后，可重新新建这条演示连接。</p></div><div class="modal-footer"><button class="button" data-confirm="cancel">取消</button><button class="button primary" data-confirm="delete">删除连接</button></div>`,true);dialog.addEventListener('click',e=>{const action=e.target.closest('[data-confirm]')?.dataset.confirm;if(action==='cancel')closeModal();if(action==='delete'){rows=rows.filter(r=>r.id!==row.id);persist();closeModal();listPage();toast('API 连接已删除');}});}
  });
  window.addEventListener('popstate',()=>{closeModal();const row=rows.find(r=>r.id===new URLSearchParams(location.search).get('id'));selected=row?.presetId||'deepseek';render();});
  return {render,closeModal};
};
